B), $font, $card['sub']); } ob_start(); imagepng($out, null, self::PNG_LEVEL); $bytes = (string) ob_get_clean(); imagedestroy($out); return $bytes; } private static function shapes(GdImage $out, int $x, int $y, int $w, int $h, callable $paint): void { $ss = self::SUPERSAMPLE; $im = imagecreatetruecolor($w * $ss, $h * $ss); imagealphablending($im, false); imagesavealpha($im, true); imagefilledrectangle($im, 0, 0, $w * $ss - 1, $h * $ss - 1, imagecolorallocatealpha($im, 0, 0, 0, 127)); imagealphablending($im, true); $paint($im, $x * $ss, $y * $ss); $tile = imagecreatetruecolor($w, $h); imagealphablending($tile, false); imagesavealpha($tile, true); imagecopyresampled($tile, $im, 0, 0, 0, 0, $w, $h, $w * $ss, $h * $ss); imagedestroy($im); imagealphablending($out, false); imagecopy($out, $tile, $x, $y, 0, 0, $w, $h); imagedestroy($tile); } private static function ring(GdImage $im, int $cx, int $cy, int $outerR, int $thick, int $track, array $segments): void { $d = $outerR * 2; imagefilledellipse($im, $cx, $cy, $d, $d, $track); $angle = -90.0; foreach ($segments as [$frac, $col]) { $frac = max(0.0, min(1.0, $frac)); $sweep = 360.0 * $frac; if ($sweep < 1.5) { $angle += $sweep; continue; } $start = $angle; $end = $angle + $sweep; $si = (int) round($start); $ei = max($si + 1, (int) round($end)); $c = self::color($im, $col); imagefilledarc($im, $cx, $cy, $d, $d, $si, $ei, $c, IMG_ARC_PIE); $mid = $outerR - (int) ($thick / 2); foreach ([$start, $end] as $a) { $rad = deg2rad($a); imagefilledellipse($im, $cx + (int) round(cos($rad) * $mid), $cy + (int) round(sin($rad) * $mid), $thick, $thick, $c); } $angle = $end; } imagealphablending($im, false); imagefilledellipse($im, $cx, $cy, ($outerR - $thick) * 2, ($outerR - $thick) * 2, imagecolorallocatealpha($im, 0, 0, 0, 127)); imagealphablending($im, true); } private static function netBars(GdImage $im, int $cx, int $top, int $bottom, array $bars, int $track, int $ss): void { $h = $bottom - $top; foreach (self::netCells($cx, $bars, 