function lighten(string $hex, float $amount): string { $hex = ltrim($hex, '#'); $r = hexdec(substr($hex, 0, 2)); $g = hexdec(substr($hex, 2, 2)); $b = hexdec(substr($hex, 4, 2)); return sprintf( '#%02x%02x%02x', (int) min(255, $r + (255 - $r) * $amount), (int) min(255, $g + (255 - $g) * $amount), (int) min(255, $b + (255 - $b) * $amount), ); } private static function color(GdImage $im, string $hex, int $alpha = 0): int { $hex = ltrim($hex, '#'); return (int) imagecolorallocatealpha($im, hexdec(substr($hex, 0, 2)), hexdec(substr($hex, 2, 2)), hexdec(substr($hex, 4, 2)), $alpha); } private static function dir(): ?string { $dir = storage_path('app/dezerx/discord-resources'); if (!is_dir($dir) && !@mkdir($dir, 0750, true) && !is_dir($dir)) { return null; } return $dir; } private static function cached(string $key): ?string { $dir = self::dir(); if ($dir === null) { return null; } self::prune($dir); $path = $dir . '/' . $key . '.png'; if (is_file($path) && (time() - filemtime($path)) <= self::REUSE_SECONDS) { $data = @file_get_contents($path); return is_string($data) && self::complete($data) ? $data : null; } return null; } private static function complete(string $data): bool { return strlen($data) > 64 && str_starts_with($data, "\x89PNG\r\n\x1a\n") && str_ends_with($data, "IEND\xaeB`\x82"); } private static function store(string $key, string $data): string { $dir = self::dir(); if ($dir !== null) { $path = $dir . '/' . $key . '.png'; $temp = $path . '.' . bin2hex(random_bytes(4)) . '.tmp'; if (@file_put_contents($temp, $data) !== false) { @chmod($temp, 0640); if (!@rename($temp, $path)) { @unlink($temp); } } } return $data; } private static function prune(string $dir): void { try { if (!Cache::add('dzb:res-prune', 1, 60)) { return; } } catch (Throwable) { } $cutoff = time() - self::PRUNE_SECONDS; foreach (glob($dir . '/*.{png,tmp}', GLOB_BRACE) ?: [] as $file) { if (filemtime($file) < $cutoff) { @unlink($file); } } } } 